#include <algorithm>
#include <cstdint>
#include <vector>

struct Range { std::uint64_t address; std::uint64_t length; };

std::vector<Range> diffSnapshots(const std::vector<std::uint8_t>& before, const std::vector<std::uint8_t>& after,
                                 std::uint64_t base, std::uint64_t mergeGap)
{
    const std::size_t n{ std::min(before.size(), after.size()) };
    std::vector<Range> ranges;
    std::size_t i{ 0 };
    while (i < n)
    {
        if (before[i] == after[i]) { ++i; continue; }
        const std::size_t start{ i };
        while (i < n && before[i] != after[i]) ++i;           // i is one past the changed run
        const Range run{ base + start, i - start };

        if (!ranges.empty())
        {
            Range& last{ ranges.back() };
            const std::uint64_t lastEnd{ last.address + last.length };
            if (run.address - lastEnd <= mergeGap)
            {
                last.length = run.address + run.length - last.address;
                continue;
            }
        }
        ranges.push_back(run);
    }
    return ranges;
}

