using Bytes = std::vector<std::uint8_t>;
TEST("separate changes")
{
    const auto r{ diffSnapshots(Bytes{ 0, 0, 0, 0, 0, 0 }, Bytes{ 0, 0x11, 0, 0x22, 0, 0 }, 0x1000, 0) };
    CHECK_EQ(r.size(), std::size_t{ 2 });
    CHECK_EQ(r[0].address, 0x1001ull); CHECK_EQ(r[0].length, 1ull);
    CHECK_EQ(r[1].address, 0x1003ull); CHECK_EQ(r[1].length, 1ull);
}
TEST("merged across a small gap")
{
    const auto r{ diffSnapshots(Bytes{ 0, 0, 0, 0, 0, 0 }, Bytes{ 0, 0x11, 0, 0x22, 0, 0 }, 0x1000, 1) };
    CHECK_EQ(r.size(), std::size_t{ 1 });
    CHECK_EQ(r[0].address, 0x1001ull); CHECK_EQ(r[0].length, 3ull);
}
TEST("a run of changes") { const auto r{ diffSnapshots(Bytes{ 1, 2, 3, 4 }, Bytes{ 9, 9, 9, 4 }, 0x40, 0) }; CHECK_EQ(r.size(), std::size_t{ 1 }); CHECK_EQ(r[0].address, 0x40ull); CHECK_EQ(r[0].length, 3ull); }
TEST("a change at the very end") { const auto r{ diffSnapshots(Bytes{ 1, 2, 3 }, Bytes{ 1, 2, 4 }, 0, 0) }; CHECK_EQ(r.size(), std::size_t{ 1 }); CHECK_EQ(r[0].address, 2ull); }
TEST("gap too large to merge") { const auto r{ diffSnapshots(Bytes{ 0, 0, 0, 0, 0 }, Bytes{ 1, 0, 0, 0, 1 }, 0, 2) }; CHECK_EQ(r.size(), std::size_t{ 2 }); }
TEST("gap exactly the limit") { const auto r{ diffSnapshots(Bytes{ 0, 0, 0, 0, 0 }, Bytes{ 1, 0, 0, 0, 1 }, 0, 3) }; CHECK_EQ(r.size(), std::size_t{ 1 }); CHECK_EQ(r[0].length, 5ull); }
TEST("no changes") { CHECK(diffSnapshots(Bytes{ 1, 2 }, Bytes{ 1, 2 }, 0, 4).empty()); }
TEST("different sizes compare the common part") { const auto r{ diffSnapshots(Bytes{ 1, 2, 3 }, Bytes{ 1, 5 }, 0, 0) }; CHECK_EQ(r.size(), std::size_t{ 1 }); CHECK_EQ(r[0].address, 1ull); CHECK_EQ(r[0].length, 1ull); }

